create table if not exists supply_recovery_approvals (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,action_id uuid not null references supply_recovery_actions(id) on delete restrict,approver_user_id uuid not null references auth.users(id),decision text not null check(decision in ('approved','rejected')),decision_hash text not null check(length(decision_hash)=64),created_at timestamptz not null default now(),unique(action_id,approver_user_id));
create index if not exists idx_v24_approvals_action on supply_recovery_approvals(action_id,created_at desc);
alter table supply_recovery_approvals enable row level security;
create policy v24_approvals_select on supply_recovery_approvals for select using(is_member(business_id));
create or replace function public.v24_hash_recovery_approval(p_business_id uuid,p_action_id uuid,p_approver_user_id uuid,p_decision text) returns text language sql immutable as $$ select encode(digest(concat_ws('|',p_business_id::text,p_action_id::text,p_approver_user_id::text,p_decision),'sha256'),'hex') $$;
create or replace function public.v24_decide_recovery_action(p_business_id uuid,p_action_id uuid,p_decision text) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; h text; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_decision not in ('approved','rejected') then raise exception 'Invalid recovery decision'; end if; if not exists(select 1 from supply_recovery_actions where id=p_action_id and business_id=p_business_id) then raise exception 'Recovery action not found'; end if; perform pg_advisory_xact_lock(hashtextextended('NABUUMA|SUPPLY_RECOVERY_APPROVAL|V2.4',0)); h:=v24_hash_recovery_approval(p_business_id,p_action_id,auth.uid(),p_decision); insert into supply_recovery_approvals(business_id,action_id,approver_user_id,decision,decision_hash) values(p_business_id,p_action_id,auth.uid(),p_decision,h) on conflict(action_id,approver_user_id) do update set decision=excluded.decision,decision_hash=excluded.decision_hash returning id into x; update supply_recovery_actions set status=case when p_decision='approved' then 'approved' else 'rejected' end,approved_at=case when p_decision='approved' then now() else approved_at end where id=p_action_id; return x; end; $$;
revoke all on function public.v24_hash_recovery_approval(uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.v24_hash_recovery_approval(uuid,uuid,uuid,text) to authenticated;
revoke all on function public.v24_decide_recovery_action(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.v24_decide_recovery_action(uuid,uuid,text) to authenticated;